-- 2026-11-w1 G2 動画レビュー: C85・C87・C89 のイラストの情景を差し替え(ユーザー指摘。問題文・答えは不変)
-- C85
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "王さまの無理難題だ!", "hint": "黒板は広いぞ!", "question": "王さまが黒板に1本の線を引いた。「この線に触れず、消しもせず、黒板も動かさずに、この線を短くしてみよ」。賢い家来はどうした?", "answer": "下に、もっと長い線を引いた", "explanation": "家来は、王さまの線の下に、もっと長い線を引いた。比べれば、元の線は「短いほう」になる。長い短いは、比べる相手で決まる。インドに伝わるとんち話だ。", "coach_comment": "比べ方ひとつで変わるぞ!", "tags": ["とんち", "夜の一問", "発想転換"], "summary": "引かれた線に触れず消さずに短くせよという難題を、下にもっと長い線を引いて解くとんち。インドのアクバルとビルバルの民話。長さは比べる相手で決まる。", "illustration_scene": "夜の研究室。壁いっぱいの大きな黒板の上のほうに、黒板の幅の半分ほどの短い白い横線が1本だけ引いてある。黒板の前に、王冠と赤いマントの王さまが後ろ姿で立って線を指さし、となりでチョークを持った家来が後ろ姿で考えこんでいる。机に本と地球儀とろうそく。黒板の右上に大きな「?」。顔は描かない。「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.question_text = '王さまが黒板に1本の線を引いた。「この線に触れず、消しもせず、黒板も動かさずに、この線を短くしてみよ」。賢い家来はどうした?';
-- C87
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "力じゃ解決しないぞ!", "hint": "ハサミのせいじゃないぞ!", "question": "よく切れるハサミで、写真を半分に切ろうとした。でも、どうしても切れない。ハサミは壊れていない。なぜ?", "answer": "スマホの画面に映っている写真だった", "explanation": "切ろうとしたのは、スマホの画面に映った写真。紙に焼いた写真ではないから、ハサミでは切れない。写真と聞くと、つい紙の1枚を思い浮かべてしまう。", "coach_comment": "思い込みを切り取ったな!", "tags": ["水平思考", "夜の一問", "状況パズル"], "summary": "よく切れるハサミで写真が切れない理由を問う水平思考。写真はスマホの画面に映っているものだった。写真=紙という思い込みを突く。", "illustration_scene": "夜の机を斜め上から見た絵。電気スタンドのあたたかい明かりが机を照らし、物の影がやわらかく落ちている。木目の机の上に、銀色に光る大きなハサミが1本と、細かく切られた色紙の切りくず、色鉛筆の入ったペン立て、マグカップ。奥の窓の外に夜の町の明かり。ハサミの上に大きな「?」。人物・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.question_text = 'よく切れるハサミで、写真を半分に切ろうとした。でも、どうしても切れない。ハサミは壊れていない。なぜ?';
-- C89
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "目を疑うとはこのことだ!", "hint": "ペンの色がカギだぞ!", "question": "赤いペンで、白い紙に大きく字を書いた。インクはちゃんと出ているのに、書いた本人にも字がまったく見えない。目は正常で、部屋の明かりもついている。なぜ?", "answer": "部屋の明かりが真っ赤だった", "explanation": "赤い明かりの下では、白い紙も赤く見える。赤い字は紙の色にとけこんで、見分けがつかない。昔の写真の暗室などが、そんな部屋だ。普通の明かりに戻せば字は現れる。", "coach_comment": "見えないものを見抜いたな!", "tags": ["水平思考", "夜の一問", "状況パズル"], "summary": "赤いペンで白い紙に書いた字が、インクが出ているのに本人にも見えない理由を問う水平思考。部屋の明かりが真っ赤で、紙も赤く見えて字がとけこんだ(暗室など)。", "illustration_scene": "夜のリビング。ソファの前のローテーブルで、後ろ姿の子どもが床に座り、大きな白い画用紙に赤いマーカーでお絵描きをしている。画用紙には何も描かれていないように見える。床にクレヨンの箱とぬいぐるみ。奥の窓のカーテンのすき間から星空。画面に入るのは床・テーブル・ソファ・窓だけ。画用紙の上に大きな「?」。顔は描かない。「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.question_text = '赤いペンで、白い紙に大きく字を書いた。インクはちゃんと出ているのに、書いた本人にも字がまったく見えない。目は正常で、部屋の明かりもついている。なぜ?';
